import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/users.db')
SECRET = os.environ.get('HMAC_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key', '')
        expected = hmac.new(SECRET.encode(), b'service-auth', hashlib.sha256).hexdigest() if hasattr(hmac, 'new') else hmac.HMAC(SECRET.encode(), b'service-auth', hashlib.sha256).hexdigest()
        if not hmac.compare_digest(api_key, expected):
            return jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/api/users/search', methods=['GET'])
@verify_api_key
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')
    limit = request.args.get('limit', '20')

    # Validate field against allowed columns
    allowed_fields = ['username', 'email', 'department', 'location']
    if field not in allowed_fields:
        return jsonify({'error': f'Invalid field. Allowed: {allowed_fields}'}), 400

    # Build query - field is validated above so safe to interpolate
    # Value is user-controlled, use parameterized query
    query = f"SELECT id, username, email, department, location FROM users WHERE {field} LIKE ? LIMIT {limit}"

    try:
        db = get_db()
        cursor = db.execute(query, (f'%{value}%',))
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'results': results, 'count': len(results)})
    except sqlite3.Error as e:
        app.logger.error(f'Database error: {e}')
        return jsonify({'error': 'internal error'}), 500

@app.route('/api/users/<int:user_id>/notes', methods=['POST'])
@verify_api_key
def add_note(user_id):
    """Add a note to a user profile. Notes are stored with attribution."""
    data = request.get_json()
    if not data or 'note' not in data:
        return jsonify({'error': 'note field required'}), 400

    author = request.headers.get('X-Author', 'system')
    note = data['note']

    db = get_db()
    db.execute(
        "INSERT INTO user_notes (user_id, author, content, created_at) VALUES (?, ?, ?, datetime('now'))",
        (user_id, author, note)
    )
    db.commit()
    return jsonify({'status': 'created'}), 201

@app.route('/api/reports/export', methods=['GET'])
@verify_api_key
def export_report():
    """Export user report. Supports custom grouping."""
    group_by = request.args.get('group', 'department')
    format_type = request.args.get('format', 'json')

    # Validate group_by
    valid_groups = ['department', 'location']
    if group_by not in valid_groups:
        return jsonify({'error': 'invalid group'}), 400

    query = f"SELECT {group_by}, COUNT(*) as count FROM users GROUP BY {group_by}"

    db = get_db()
    cursor = db.execute(query)
    results = [dict(row) for row in cursor.fetchall()]

    if format_type == 'csv':
        lines = [f"{group_by},count"]
        for row in results:
            lines.append(f"{row[group_by]},{row['count']}")
        return '\n'.join(lines), 200, {'Content-Type': 'text/csv'}

    return jsonify({'report': results})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
